by_site_id.map:
function(doc) {
  if (doc.type !== "field_capture") return;
  var siteId = (doc.site_id || "").toString().trim();
  if (!siteId) return;
  var capturedAt = doc.captured_at || doc.exported_at || doc.created_at || "";
  emit([siteId, capturedAt, doc.capture_id || doc._id], {
    _id: doc._id,
    type: doc.type,
    capture_id: doc.capture_id || doc._id,
    site_id: siteId,
    site: doc.site || "",
    person_id: doc.person_id || "",
    person_name: doc.person_name || "",
    qc_category: doc.qc_category || "",
    phase: doc.phase || "",
    note: doc.note || "",
    captured_at: doc.captured_at || "",
    exported_at: doc.exported_at || "",
    created_at: doc.created_at || "",
    photos: doc.photos || [],
    audio: doc.audio || []
  });
}

by_upload_id.map:
function(doc) {
  if (doc.type !== "field_capture") return;
  var targetType = doc.target_type || "location";
  var targetId = (doc.target_id || doc.site_id || "").toString().trim();
  var siteId = (doc.site_id || "").toString().trim();
  // Skip docs that genuinely have no target. Post-prompt-133
  // every capture has either site_id (location) or target_id
  // (prospect), so this should never fire in practice.
  if (!targetId) return;
  function emitUploads(records) {
    if (!records) return;
    for (var i = 0; i < records.length; i++) {
      var record = records[i] || {};
      if (record.upload_id) {
        emit(record.upload_id, {
          target_type: targetType,
          target_id: targetId,
          site_id: siteId
        });
      }
    }
  }
  emitUploads(doc.photos);
  emitUploads(doc.audio);
}

validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  if (newDoc._deleted) return;
  if (newDoc._id && newDoc._id.indexOf('_design/') === 0) return;

  var allowedTypes = {
    "field_capture": true,
    "action_candidate": true,
    "job_draft": true
  };

  if (!newDoc.type || !allowedTypes[newDoc.type]) {
    throw({forbidden: 'Document type must be an allowed btq_field_captures type.'});
  }

  if (newDoc.type === 'action_candidate') {
    if (!newDoc.candidate_id) {
      throw({forbidden: 'action_candidate requires candidate_id.'});
    }
    if (!newDoc.status) {
      throw({forbidden: 'action_candidate requires status.'});
    }
    var allowedStatuses = {
      "pending_review": true,
      "approved": true,
      "rejected": true,
      "failed": true
    };
    if (!allowedStatuses[newDoc.status]) {
      throw({forbidden: 'action_candidate status must be pending_review, approved, rejected, or failed.'});
    }
  }

  if (newDoc.type === 'job_draft') {
    if (newDoc.draft_id === null || newDoc.draft_id === undefined || !newDoc.draft_id.toString().trim()) {
      throw({forbidden: 'job_draft requires draft_id.'});
    }
    if (newDoc.job_type === null || newDoc.job_type === undefined || !newDoc.job_type.toString().trim()) {
      throw({forbidden: 'job_draft requires job_type.'});
    }
    var allowedReviewStatuses = {
      "pending_approval": true,
      "approved": true,
      "rejected": true
    };
    if (!newDoc.review_status || !allowedReviewStatuses[newDoc.review_status]) {
      throw({forbidden: 'job_draft review_status must be pending_approval, approved, or rejected.'});
    }
  }
}
